def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3]
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)

    marker = next((r, c) for r, c in cells
                  if top < r < bottom and left < c < right)

    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            if (r, c) == marker:
                continue
            out[r][c] = 2 if max(abs(r - marker[0]), abs(c - marker[1])) in (2, 4) else 4
    return out
